-- Migration 20261031133134_obligation_strategy: generated by drizzle-kit, hand-reviewed before commit.
-- Reviewed-by: Claude (agent, #724)
-- Strategy-bearing obligation descriptions are hidden from clerks (R16 of #67, #724):
--   * obligation.strategy: set by an owner or advocate (the service checks), default false.
--   * obligation_clerk_v: the clerk column-scoped view. Every obligation column, with description NULL
--     on strategy rows, so a clerk still sees the task (due date, status) but not the note. It is
--     hand-written instead of app_clerk_view() because that helper drops a column for every row.
--     security_barrier; it runs with its owner's rights, and obligation is under FORCE RLS with no
--     policy for causedeck_owner, so row-level security still applies through it.
--   * the clerk role loses every privilege on obligation: a clerk reads the view only. Clerk
--     obligation writes (tasks, copies, defects) run in the app role, gated by can() in the service.
ALTER TABLE "obligation" ADD COLUMN "strategy" boolean DEFAULT false NOT NULL;;--> statement-breakpoint
CREATE VIEW "obligation_clerk_v" WITH (security_barrier = true) AS SELECT id, workspace_id, matter_id, proceeding_id, source, CASE WHEN strategy THEN NULL ELSE description END AS description, strategy, due_date, basis, owner_member_id, status, closed_reason_type, closed_by, closed_at, closed_note, source_order_id, source_type, source_ref, anchor_id, confidence, confirmation_state, captured_at, created_at, updated_at FROM "obligation";--> statement-breakpoint
REVOKE ALL ON "obligation" FROM causedeck_clerk;--> statement-breakpoint
REVOKE ALL ON "obligation_clerk_v" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT ON "obligation_clerk_v" TO causedeck_app, causedeck_clerk;
